// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface BloodStatisticsOut {
  date_from: string;
  date_to: string;
  units_received: number;
  units_transfused: number;
  reactions: number;
  /** Reactions per 100 units transfused; null with none transfused */
  reaction_pct: number | null;
  units_discarded: number;
  /** Units discarded per 100 received in the period */
  wastage_pct: number | null;
  discarded_by_reason: BloodDiscardCountOut[];
  units_returned_to_source: number;
  component_units_transfused: number;
  /** Units transfused that were components, not whole blood */
  component_usage_pct: number | null;
  transfused_by_component: BloodComponentCountOut[];
  /** From the request to its first unit issued */
  issue_turnaround: BloodTurnaroundOut[];
  transfusions_ended_late: number;
}

export interface BloodDiscardCountOut {
  discard_reason: "Expired" | "BagDamaged" | "OutOfStorageTooLong" | "StorageTemperature" | "IdentityDiscrepancy" | "Other";
  n: number;
}

export interface BloodComponentCountOut {
  component: "WholeBlood" | "RedCells" | "FreshFrozenPlasma" | "Cryoprecipitate" | "Platelets";
